ROOT.scriptdef:
CREATE PROCEDURE [CDN].[POS_EksportGrupyTowarow] @rowVersion bigint, @PointOfSaleId int AS BEGIN SET NOCOUNT ON;
declare @LastMod BIGINT = isnull((select max(TwG_CzasModyfikacji) from cdn.PicoKonfig join cdn.PicoStanowiska on pck_picoid = psa_pckid outer apply cdn.PobierzDrzewoGrupTowarowych(PcK_TwGENumer,DEFAULT,DEFAULT,1,DEFAULT,DEFAULT) join cdn.TwrGrupy on GIDNumer=TwG_GIDNumer and GIDTyp=TwG_GIDTyp where psa_id = @PointOfSaleId and TwG_CzasModyfikacji > @rowVersion),@rowVersion)
SELECT @LastMod AS [@RowVersion] ,(select Gidnumer as [@Id], Kod as [@Name], -- as [@CategoryId], NULL 'true' as [@IsActive], 'false' as [@IsAnalytical], Sciezka as [@HierarchyPath] from cdn.PicoKonfig join cdn.PicoStanowiska on pck_picoid = psa_pckid outer apply cdn.PobierzDrzewoGrupTowarowych(PcK_TwGENumer,DEFAULT,DEFAULT,1,DEFAULT,DEFAULT) join cdn.TwrGrupy on GIDNumer=TwG_GIDNumer and GIDTyp=TwG_GIDTyp where psa_id = @PointOfSaleId and (TwG_CzasModyfikacji > @rowVersion OR @rowVersion = 0) for xml path('ProductGroup'), type) for xml path('ProductGroups') SET NOCOUNT OFF; END
